import{_ as i,l as p,o as r,c as s,v as t,p as n,x as o,d as l,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"Hopcroft–Karp","description":"","frontmatter":{"title":"Hopcroft–Karp","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hopcroft-karp.md","filePath":"cs/hopcroft-karp.md","lastUpdated":1789023840000}'),h={name:"cs/hopcroft-karp.md"};function f(E,a,_,m,u,S){const e=p("Mermaid");return r(),s("div",null,[a[1]||(a[1]=t('<h1 id="hopcroft–karp" tabindex="-1">Hopcroft–Karp <a class="header-anchor" href="#hopcroft–karp" aria-label="Permalink to &quot;Hopcroft–Karp&quot;">​</a></h1><div class="epigraph"><p>二分图上一次 BFS 找出全体最短增广路，再 DFS 同时增广，相位 $O(\\sqrt V)$，总 $O(E\\sqrt V)$。</p><footer>—— 据 Hopcroft and Karp, An $n^{5/2}$ Algorithm for Maximum Matchings in Bipartite Graphs, 1973；CLRS 第 26.3 节整理</footer></div><p>上一课<a href="/cs/min-cut-applications">最小割的建模</a>把划分交给最大流。主干<a href="/cs/bipartite-match">二分图匹配</a>已用单位容量流给出最大匹配。缺口是<strong>更快的增广组织</strong>：Hopcroft–Karp 与单位网络上 Dinic 同类，不把每条交错路单独 BFS 到底。不重写 König。后课带权匹配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>匈牙利：一次找一条增广路 \\(O(E)\\)，最多 \\(V\\) 次，\\(O(VE)\\)。Hopcroft–Karp：残量（自由点、\\(L\\to R\\) 非匹配、\\(R\\to L\\) 匹配）上 BFS，只保留到自由 \\(R\\) 的最短距离分层；再在分层里 DFS 找极大一组<strong>顶点不交</strong>的最短增广，同时翻转。相位数 \\(O(\\sqrt V)\\)：短增广做完后，剩余增广至少长 \\(\\sqrt V\\) 量级，条数受匹配规模限制。总 \\(O(E\\sqrt V)\\)。</p><p>缺口是「一批最短」，不是新的匹配定义。Berge 增广路定理仍是正确性根。</p><h3 id="与-dinic-同一张分层" tabindex="-1">与 Dinic 同一张分层 <a class="header-anchor" href="#与-dinic-同一张分层" aria-label="Permalink to &quot;与 Dinic 同一张分层&quot;">​</a></h3><p>单位容量 \\(s\\)–\\(L\\)–\\(R\\)–\\(t\\) 上 Dinic 的阻塞流，在二分匹配里就是这批最短增广。本课用匹配语言写，便于后课 KM、带花对照。不要声称一般图也 \\(O(E\\sqrt V)\\)——一般图要 Micali–Vazirani 等，更重。</p><p><span class="marginnote">Hopcroft–Karp 1973。Dinic 1970 更早给出分层阻塞流。CLRS 26.3 用流，竞赛实现常写 HK 的 BFS+DFS。后课 Kuhn–Munkres 处理权。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>重复：从全体自由 \\(L\\) BFS 分层，若无自由 \\(R\\) 则停。DFS 从自由 \\(L\\) 沿层 \\(+1\\) 边增广，点用过即占用。翻转匹配边。直到 BFS 失败。</p>',11)),(r(),n(d,null,{default:o(()=>[c(e,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BFS%5B%22BFS%20%E6%9C%80%E7%9F%AD%E5%88%86%E5%B1%82%22%5D%20--%3E%20DFS%5B%22%E5%90%8C%E6%97%B6%E5%A4%9A%E6%9D%A1%E6%9C%80%E7%9F%AD%E5%A2%9E%E5%B9%BF%22%5D%0A%20%20DFS%20--%3E%20M%5B%22%E6%9B%B4%E6%96%B0%E5%8C%B9%E9%85%8D%22%5D%0A%20%20M%20--%3E%20BFS%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>实现注意：一轮内每个点至多一次。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最短增广长度不减。一轮吃掉该长度的极大不交组后，下一轮更长。分析把相位分成「短于 \\(\\sqrt V\\)」与之后，得到 \\(O(\\sqrt V)\\) 轮。与普通匈牙利比，只改调度，不改交错路翻转。</p><p>稠密图 \\(E=\\Theta(V^2)\\) 时 \\(O(V^{2.5})\\)，仍优于 \\(O(VE)\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写一般图匹配、不写带权。不把 Hall 条件再证一遍。后课默认：二分最大基数匹配实用 \\(O(E\\sqrt V)\\)。下一课 KM / 匈牙利带权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一批最短增广 = 二分匹配的 Dinic。</li><li>\\(O(E\\sqrt V)\\)；正确性仍是增广路定理。</li><li>一般图不是本课的界。</li><li>出处：Hopcroft and Karp, 1973。</li></ul>',8))])}const D=i(h,[["render",f]]);export{q as __pageData,D as default};
